import subprocess, re, os
from collections import defaultdict

def git(cmd):
    return subprocess.check_output(cmd, shell=True, text=True)

commits=[]
for b in ['rachel','monica','phoebe','joey','chandler','ross']:
    out=git(f"git log --format='%H' origin/friend/{b}")
    for sha in out.split():
        body=git(f"git show -s --format='%B' {sha}")
        if re.search(r'^Friend-Message:\s*1\s*$', body, re.M) and re.search(r'^Speaker:\s*\w', body, re.M) and re.search(r'^Episode:\s*\S+', body, re.M):
            m=re.search(r'Episode:\s*(\S+)', body)
            ep=m.group(1)
            commits.append((sha,b,ep))

main_dir='/home/runner/work/ross-work/main'
present=set()
for root,_,files in os.walk(main_dir):
    for f in files:
        if f.endswith('.md'):
            txt=open(os.path.join(root,f)).read()
            for sha,b,ep in commits:
                if sha in txt:
                    present.add(sha)

missing=[c for c in commits if c[0] not in present]
print("total real utterances:", len(commits), "missing:", len(missing))
byep=defaultdict(list)
for sha,b,ep in missing:
    byep[ep].append((sha,b))
for ep in sorted(byep):
    print(ep, len(byep[ep]))
    for sha,b in byep[ep]:
        print("   ", b, sha)
